// Get all items passed from the Notion trigger node
const items = $input.all();
const output = [];

// Get today's date (at midnight to keep date math precise)
const today = new Date();
today.setHours(0, 0, 0, 0);

for (let item of items) {
  const data = item.json;

  const supplierName = data["property_supplier_name"] || data["name"];
  const status = data["property_status"];
  const contactEmail = data["property_contact_email"];
  const certType = data["property_certification_type"];

  // Extracting from Notion's nested object format safely
  const expiryObj = data["property_certification_expiry"];
  const expiryStr = expiryObj && typeof expiryObj === 'object' ? expiryObj.start : expiryObj;

  const lastAlertObj = data["property_last_compliance_alert"];
  const lastAlertStr = lastAlertObj && typeof lastAlertObj === 'object' ? lastAlertObj.start : lastAlertObj;

  // 1. Skip if supplier is explicitly deactivated or manually handled
  if (status === 'Offboarded' || status === 'In Requalification') {
    continue;
  }

  // 2. Edge Case Guard: Handle truly missing expiry dates
  if (!expiryStr) {
    output.push({
      json: {
        ...data,
        daysRemaining: null,
        actionRequired: "ESCALATE_MISSING_DATA",
        reason: `Supplier ${supplierName} is active but has no recorded expiry date.`
      }
    });
    continue;
  }

  const expiryDate = new Date(expiryStr);
  expiryDate.setHours(0, 0, 0, 0);

  // Calculate the difference in days
  const timeDiff = expiryDate.getTime() - today.getTime();
  const daysRemaining = Math.ceil(timeDiff / (1000 * 60 * 60 * 24));

  let actionRequired = "IGNORE_COMPLIANT"; 
  let reason = "Supplier is fully compliant.";

  // Anti-Spam Guard: Check if we alerted them within the last 14 days
  let recentlyAlerted = false;
  if (lastAlertStr) {
    const lastAlertDate = new Date(lastAlertStr);
    const alertAgeDiff = today.getTime() - lastAlertDate.getTime();
    const daysSinceAlert = Math.floor(alertAgeDiff / (1000 * 60 * 60 * 24));
    if (daysSinceAlert <= 14) {
      recentlyAlerted = true;
    }
  }

  // 3. Bracket Assignment & Logic Rules
  if (daysRemaining < 0) {
    if (recentlyAlerted) {
      actionRequired = "IGNORE_ALREADY_NOTIFIED";
      reason = `Expired (${Math.abs(daysRemaining)} days ago), but an alert was sent recently. Anti-spam engaged.`;
    } else {
      actionRequired = "CRITICAL_BREACH";
      reason = `CRITICAL: Certification expired ${Math.abs(daysRemaining)} days ago. Escalation required.`;
    }
  } else if (daysRemaining <= 14) {
    if (recentlyAlerted) {
      actionRequired = "IGNORE_ALREADY_NOTIFIED";
      reason = `Expiring soon (${daysRemaining} days remaining), but already alerted recently.`;
    } else {
      actionRequired = "ALERT_14_DAYS";
      reason = `URGENT: Certification expires in ${daysRemaining} days. Needs high-priority alert.`;
    }
  } else if (daysRemaining <= 30) {
    if (recentlyAlerted) {
      actionRequired = "IGNORE_ALREADY_NOTIFIED";
      reason = `Expiring in 30-day window, but already alerted recently.`;
    } else {
      actionRequired = "ALERT_30_DAYS";
      reason = `WARNING: Compliance routine renewal window open (${daysRemaining} days remaining).`;
    }
  }

  // Filter out the non-actionable elements to prevent unnecessary node executions down the line
  if (actionRequired !== "IGNORE_COMPLIANT" && actionRequired !== "IGNORE_ALREADY_NOTIFIED") {
    output.push({
      json: {
        ...data,
        daysRemaining: daysRemaining,
        actionRequired: actionRequired,
        reason: reason
      }
    });
  }
}

return output;

